#!/bin/bash
# exit 0 when totalWithTax(100, 1) == 118, exit 1 otherwise
d=$(mktemp -d)
cp src/main/java/com/example/orders/OrderService.java "$d/"
cat > "$d/Check.java" <<'J'
package com.example.orders;
public class Check {
    public static void main(String[] a) {
        double v = new OrderService().totalWithTax(100, 1);
        System.exit(Math.abs(v - 118.0) < 0.001 ? 0 : 1);
    }
}
J
(cd "$d" && javac -d out OrderService.java Check.java && java -cp out com.example.orders.Check)
rc=$?; rm -rf "$d"; exit $rc

import java.util.Map;

public class FlagDemo {
    record Flags(Map<String, String> env) {
        boolean enabled(String name) {
            return Boolean.parseBoolean(env.getOrDefault("FEATURE_" + name, "false"));
        }
    }

    static double price(double base, Flags flags) {
        if (flags.enabled("NEW_DISCOUNT")) {
            return base * 0.90;
        }
        return base;
    }

    public static void main(String[] args) {
        Flags flags = new Flags(System.getenv());
        System.out.println("price = " + price(200.0, flags));
    }
}
